const ERROR: f64 = f64::from_bits(0x3d0c_c000_0000_000c);

/// `axis_gap`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: P3, b: P3, c: P3, g: i128) -> Option<Sign> {
    let e_x = exact_f64(b.x) - exact_f64(a.x);
    let e_y = exact_f64(b.y) - exact_f64(a.y);
    let e_z = exact_f64(b.z) - exact_f64(a.z);
    let w_x = exact_f64(c.x) - exact_f64(a.x);
    let w_y = exact_f64(c.y) - exact_f64(a.y);
    let w_z = exact_f64(c.z) - exact_f64(a.z);
    let u_x_1 = w_y * e_z;
    let u_x_2 = w_z * e_y;
    let u_x = u_x_1 - u_x_2;
    let u_y_1 = w_z * e_x;
    let u_y_2 = w_x * e_z;
    let u_y = u_y_1 - u_y_2;
    let u_z_1 = w_x * e_y;
    let u_z_2 = w_y * e_x;
    let u_z = u_z_1 - u_z_2;
    let uu_1 = u_x * u_x;
    let uu_2 = u_y * u_y;
    let uu_3 = uu_1 + uu_2;
    let uu_4 = u_z * u_z;
    let uu = uu_3 + uu_4;
    let ee_1 = e_x * e_x;
    let ee_2 = e_y * e_y;
    let ee_3 = ee_1 + ee_2;
    let ee_4 = e_z * e_z;
    let ee = ee_3 + ee_4;
    let g = rounded_f64(g, 42)?;
    let delta_1 = g * g;
    let delta_2 = delta_1 * ee;
    let delta = uu - delta_2;
    let m_x = largest_magnitude([e_x, w_x]);
    let m_y = largest_magnitude([e_y, w_y]);
    let m_z = largest_magnitude([e_z, w_z]);
    let m_g = largest_magnitude([g]);
    let scale = larger(m_z * m_z * m_g * m_g, m_y * m_y * m_g * m_g);
    let scale = larger(scale, m_y * m_y * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_g * m_g);
    let scale = larger(scale, m_x * m_x * m_z * m_z);
    let scale = larger(scale, m_x * m_x * m_y * m_y);
    decide(delta, ERROR, scale)
}

/// `axis_gap`'s exact value: each step in the type its certificate gives it, with checked
